(function () {
  var KB = {"faqs": [{"id": "siete-un-team-proveniente-da-google-cracovia", "q": "Are you a team from Google Kraków?", "a": "Yes. Easy Tag is the spin-off of the Italian team that worked on tags in Kraków. The story is told on About .", "href": "/en/faq#siete-un-team-proveniente-da-google-cracovia"}, {"id": "cosa-ricevo-dopo-l-acquisto", "q": "What do I receive after purchase?", "a": "The Google Tag Manager container JSON file and the instructions, by email. Ready-made containers are in the Shop .", "href": "/en/faq#cosa-ricevo-dopo-l-acquisto"}, {"id": "i-prezzi-includono-l-iva", "q": "Do prices include VAT?", "a": "Yes. All listed prices are VAT included.", "href": "/en/faq#i-prezzi-includono-l-iva"}, {"id": "perche-alcuni-prodotti-sono-su-preventivo", "q": "Why are some products on a quote?", "a": "E-commerce, Dynamic Remarketing and Consent Mode depend on the CMS and the data layer. The product pages are E-commerce Tracker , Dynamic Remarketing and Consent Mode v2 .", "href": "/en/faq#perche-alcuni-prodotti-sono-su-preventivo"}, {"id": "cos-e-esattamente-il-datalayer-nella-tag-platform-di-google", "q": "What exactly is the dataLayer in the Google Tag Platform?", "a": "The dataLayer is a global JavaScript array, by default window.dataLayer , that passes variables and events from the page to Google Tag Manager and to gtag.js . Prices, ids or form states are not read from the DOM. Containers such as the E-commerce Tracker and Dynamic Remarketing depend on this layer.", "href": "/en/faq#cos-e-esattamente-il-datalayer-nella-tag-platform-di-google"}, {"id": "perche-il-datalayer-si-inizializza-con-window-datalayer-window-datalayer", "q": "Why is the dataLayer initialized with window.dataLayer = window.dataLayer || [] before the snippet?", "a": "To create the array only if it does not exist, without deleting pushes that are already there. GTM and gtag.js then find a valid instance at startup. The Google Tag Manager snippet must load after this line, as described in the installation section of this guide.", "href": "/en/faq#perche-il-datalayer-si-inizializza-con-window-datalayer-window-datalayer"}, {"id": "cosa-succede-se-si-sovrascrive-window-datalayer-o-window-datalayer-dopo-", "q": "What happens if you overwrite window.dataLayer = [] or window.dataLayer = {} after load?", "a": "You break the reference on which GTM and gtag.js attached listeners and the internal queue. Events already in the queue are lost. Tags do not fire, or they fire with inconsistent data. Do not use an object {} : the dataLayer is an array, not a map.", "href": "/en/faq#cosa-succede-se-si-sovrascrive-window-datalayer-o-window-datalayer-dopo-"}, {"id": "come-elabora-i-messaggi-il-datalayer", "q": "How does the dataLayer process messages?", "a": "With a FIFO queue (First-In, First-Out): pushes are read one at a time, in arrival order. If the message contains event , Google Tag Manager evaluates the triggers and fires the linked tags before moving to the next message.", "href": "/en/faq#come-elabora-i-messaggi-il-datalayer"}, {"id": "cosa-significa-che-un-datalayer-push-da-uno-script-esterno-o-da-un-custo", "q": "What does it mean that a dataLayer.push() from an external script or from a Custom HTML tag is queued?", "a": "Execution is asynchronous relative to events already in the queue. A variable written without event may not be visible yet when the next event fires. To stay in sync, always send a dedicated event key and use a Custom Event trigger. That is how Phone Click Tracking and the Email Tag publish the click.", "href": "/en/faq#cosa-significa-che-un-datalayer-push-da-uno-script-esterno-o-da-un-custo"}, {"id": "perche-e-sconsigliato-mettere-gtag-js-dentro-un-tag-html-personalizzato-", "q": "Why is it discouraged to put gtag.js inside a custom HTML tag in GTM?", "a": "Because it duplicates the tag lifecycle, can conflict on the queue and on gtag() , and skips GTM's native controls, including consent. Use the native tag templates for Google Ads , Google Analytics 4 and Floodlight.", "href": "/en/faq#perche-e-sconsigliato-mettere-gtag-js-dentro-un-tag-html-personalizzato-"}, {"id": "come-si-inviano-un-evento-e-piu-variabili-in-un-solo-push", "q": "How do you send an event and several variables in a single push?", "a": "With one object: dataLayer.push({event: 'customize', color: 'red', conversionValue: 50}) . All keys enter the dataLayer state and can be read by tags fired by that event. Do not split the value and the event name into two different pushes.", "href": "/en/faq#come-si-inviano-un-evento-e-piu-variabili-in-un-solo-push"}, {"id": "cosa-accade-se-si-esegue-il-push-di-una-variabile-con-lo-stesso-nome-di-", "q": "What happens if you push a variable with the same name as an existing key?", "a": "The new value overwrites the previous one in the current state, from that point in the queue onward. Messages already processed are not rewritten.", "href": "/en/faq#cosa-accade-se-si-esegue-il-push-di-una-variabile-con-lo-stesso-nome-di-"}, {"id": "quanto-restano-attive-le-variabili-inserite-nel-datalayer", "q": "How long do variables pushed into the dataLayer stay active?", "a": "They remain available for the whole time spent on that page, until you overwrite them or reset the state. Across pages they must be published again on every load, with the same name: visitorType on one page and visitor_type on another are two different keys.", "href": "/en/faq#quanto-restano-attive-le-variabili-inserite-nel-datalayer"}, {"id": "qual-e-la-differenza-tra-datalayer-push-function-e-gtag", "q": "What is the difference between dataLayer.push(function) and gtag(...)?", "a": "If you pass a function to dataLayer.push(function(){ ... }) , this points to GTM's abstract data model ( this.set , this.get , this.reset ). gtag(function(){ ... }) is not a valid command: the function is ignored.", "href": "/en/faq#qual-e-la-differenza-tra-datalayer-push-function-e-gtag"}, {"id": "a-cosa-serve-this-reset-dentro-una-funzione-passata-a-datalayer-push", "q": "What is this.reset() for inside a function passed to dataLayer.push()?", "a": "It clears the state accumulated in the data model. It is useful on pages that stay open for a long time and in single-page applications, so you do not carry values from the previous view. The SPA pageview must then be sent again as described in the Google Analytics 4 guide.", "href": "/en/faq#a-cosa-serve-this-reset-dentro-una-funzione-passata-a-datalayer-push"}, {"id": "come-si-usano-this-set-e-this-get-nei-metodi-personalizzati-del-datalaye", "q": "How do you use this.set() and this.get() in custom dataLayer methods?", "a": "They read and write key-value pairs on the abstract data model, in a controlled way. Example: this.set('time', new Date()) and, in a later step, this.get('time') . They do not replace a dataLayer.push with event when you need to fire a tag.", "href": "/en/faq#come-si-usano-this-set-e-this-get-nei-metodi-personalizzati-del-datalaye"}, {"id": "si-puo-rinominare-datalayer", "q": "Can dataLayer be renamed?", "a": "Yes. Change the array name in the snippet, pass l=myNewName in the GTM script URL and align every call to window.myNewName.push(...) . If even one integration keeps writing to dataLayer , events split across two queues.", "href": "/en/faq#si-puo-rinominare-datalayer"}, {"id": "quali-sono-gli-errori-sintattici-piu-frequenti-su-datalayer-push", "q": "What are the most common syntax errors on dataLayer.push()?", "a": "datalayer.push instead of dataLayer.push (the L is uppercase). Keys with special characters, such as new-variable , written without quotes. Malformed JSON: trailing comma, single quotes where the parser expects strict JSON, unclosed brackets.", "href": "/en/faq#quali-sono-gli-errori-sintattici-piu-frequenti-su-datalayer-push"}, {"id": "come-si-verifica-in-tempo-reale-lo-stato-del-datalayer", "q": "How do you check the dataLayer state in real time?", "a": "With Google Tag Assistant on tagassistant.google.com, or with Google Tag Manager Preview mode. For each event in sequence you see the dataLayer values and the consent state. Consent is covered in more depth in the Consent Mode guide.", "href": "/en/faq#come-si-verifica-in-tempo-reale-lo-stato-del-datalayer"}, {"id": "cos-e-il-tag-google-gtag-js-e-come-si-collega-a-piu-destinazioni", "q": "What is the Google tag (gtag.js) and how does it connect to multiple destinations?", "a": "It is a single JavaScript framework that collects data and routes it to multiple destinations: Google Ads, Google Analytics, Floodlight and others, through a TAG_ID or linked configurations. In a GTM container the same role is played by native tags, not by a second copy of gtag pasted on the page.", "href": "/en/faq#cos-e-il-tag-google-gtag-js-e-come-si-collega-a-piu-destinazioni"}, {"id": "qual-e-il-ruolo-del-prefisso-dell-id-gtm-g-aw-nell-url-dello-script", "q": "What is the role of the ID prefix (GTM-, G-, AW-) in the script URL?", "a": "It tells the loader which kind of container it is starting and which permissions to apply. GTM- is a Google Tag Manager container. G- is a Google Analytics 4 property. AW- is a Google Ads account.", "href": "/en/faq#qual-e-il-ruolo-del-prefisso-dell-id-gtm-g-aw-nell-url-dello-script"}, {"id": "perche-gtag-config-e-indicato-come-deprecato-negli-snippet-piu-recenti", "q": "Why is gtag('config', ...) marked as deprecated in newer snippets?", "a": "Google is moving destination configuration into the Google Tag Manager interface and, on the page, toward gtag('set', ...) . A gtag('config') that is already published stays backward compatible: do not remove it mid-migration without a measurement plan.", "href": "/en/faq#perche-gtag-config-e-indicato-come-deprecato-negli-snippet-piu-recenti"}, {"id": "come-funziona-il-raggruppamento-e-l-instradamento-in-gtag-js", "q": "How do grouping and routing work in gtag.js?", "a": "You can centralize shared parameters and send an event only to some destinations, for example a Measurement ID G- or an account AW- , instead of sending everything everywhere. It is the same principle as the send_to parameter explained in the Google Ads native tag guide.", "href": "/en/faq#come-funziona-il-raggruppamento-e-l-instradamento-in-gtag-js"}, {"id": "come-si-verifica-nella-scheda-rete-che-il-tag-stia-trasmettendo", "q": "How do you check in the Network tab that the tag is sending data?", "a": "Filter requests by domain. googletagmanager.com loads the container. google-analytics.com or analytics.google.com carry GA4 hits. googleadservices.com and Google advertising domains carry Ads. doubleclick.net appears with Floodlight.", "href": "/en/faq#come-si-verifica-nella-scheda-rete-che-il-tag-stia-trasmettendo"}, {"id": "come-cambia-il-debug-con-il-tagging-lato-server", "q": "How does debugging change with server-side tagging?", "a": "In the browser you see requests to your tagging endpoint, usually a first-party subdomain. Hits to the final Google Ads and Google Analytics servers leave from the server container, not from the user's browser.", "href": "/en/faq#come-cambia-il-debug-con-il-tagging-lato-server"}, {"id": "cos-e-il-gateway-del-tag-google-per-gli-inserzionisti", "q": "What is the Google tag gateway for advertisers?", "a": "It is a setup that routes tag requests through a first-party path you control. It makes measurement more continuous when the browser limits third-party scripts, always in line with Consent Mode .", "href": "/en/faq#cos-e-il-gateway-del-tag-google-per-gli-inserzionisti"}, {"id": "come-si-gestisce-il-tagging-sulle-pagine-amp-rispetto-al-web-standard", "q": "How is tagging handled on AMP pages compared with the standard web?", "a": "AMP has native components for tags and for GTM, with their own limits. GTM for AMP does not cover Google Analytics the way the web does: you need dedicated AMP snippets and you must check that cid and gclid are passed to non-AMP pages.", "href": "/en/faq#come-si-gestisce-il-tagging-sulle-pagine-amp-rispetto-al-web-standard"}, {"id": "come-si-filtra-il-traffico-di-integrazioni-cms-per-esempio-shopify-in-go", "q": "How do you filter traffic from CMS integrations, for example Shopify, in Google Analytics?", "a": "With data filters or dedicated exclusions, so automatic CMS events and internal traffic do not inflate sessions and conversions. The funnel you want to read in reports is the E-commerce Tracker 's, not the theme's test funnel.", "href": "/en/faq#come-si-filtra-il-traffico-di-integrazioni-cms-per-esempio-shopify-in-go"}, {"id": "perche-usare-un-solo-datalayer-per-pagina-anche-con-piu-tag", "q": "Why use a single dataLayer per page even with multiple tags?", "a": "A single array keeps one timeline. Two separate queues make a tag read missing or stale values. The same applies when GA4, Google Ads and the Consent Mode v2 tag live on the same page.", "href": "/en/faq#perche-usare-un-solo-datalayer-per-pagina-anche-con-piu-tag"}, {"id": "qual-e-la-differenza-tra-eventi-automatici-misurazione-avanzata-eventi-c", "q": "What is the difference between automatic events, enhanced measurement, recommended events and custom events?", "a": "They are four levels, from the most generic to the most specific to you. Automatic: they fire without extra configuration. Enhanced measurement: scroll, outbound clicks, site search, video, downloads. Recommended: Google's standard names and parameters, useful for reports and features.", "href": "/en/faq#qual-e-la-differenza-tra-eventi-automatici-misurazione-avanzata-eventi-c"}, {"id": "perche-google-analytics-invia-page-view-all-avvio-del-tag", "q": "Why does Google Analytics send page_view when the tag starts?", "a": "Because the Google tag configuration sends a page_view hit by default, unless you turn it off with send_page_view: false . You turn it off in SPAs and when the dataLayer publishes the pageview, as explained in the DataLayer guide.", "href": "/en/faq#perche-google-analytics-invia-page-view-all-avvio-del-tag"}, {"id": "come-si-invia-un-evento-con-gtag-js-e-quali-parametri-accetta", "q": "How do you send an event with gtag.js and which parameters does it accept?", "a": "Syntax: gtag('event', 'event_name', { parameter: value }) . The second argument is the event name. The third is an object of event parameters or of routing toward a destination.", "href": "/en/faq#come-si-invia-un-evento-con-gtag-js-e-quali-parametri-accetta"}, {"id": "qual-e-la-differenza-tra-parametri-evento-e-proprieta-utente", "q": "What is the difference between event parameters and user properties?", "a": "Event parameters describe that single occurrence: currency , value , transaction_id , search_term . User properties describe who performs the action and persist on later interactions: plan, customer type, region.", "href": "/en/faq#qual-e-la-differenza-tra-parametri-evento-e-proprieta-utente"}, {"id": "come-si-tracciano-le-conversioni-cioe-gli-eventi-chiave-in-google-analyt", "q": "How do you track conversions, that is key events, in Google Analytics?", "a": "You send the event with the correct name and parameters, then mark it as a key event in the GA4 property. Typical names: purchase , generate_lead , sign_up . For phone, email and WhatsApp the signal comes from the Phone Click Tracking , Email Tag and Contacts 3-in-1 containers.", "href": "/en/faq#come-si-tracciano-le-conversioni-cioe-gli-eventi-chiave-in-google-analyt"}, {"id": "quali-parametri-sono-critici-per-l-evento-purchase", "q": "Which parameters are critical for the purchase event?", "a": "transaction_id , unique, so the same order is not counted twice. value , a number, not a string. currency , a three-letter ISO code, for example EUR . items , with item_id , item_name , price , quantity . They are the same fields as the E-commerce Tracker .", "href": "/en/faq#quali-parametri-sono-critici-per-l-evento-purchase"}, {"id": "perche-transaction-id-deve-essere-univoco-nell-evento-purchase", "q": "Why must transaction_id be unique on the purchase event?", "a": "Because GA4 deduplicates orders with the same id. A reload of the thank-you page or a double send must not become two purchases.", "href": "/en/faq#perche-transaction-id-deve-essere-univoco-nell-evento-purchase"}, {"id": "come-e-fatto-l-array-items-negli-eventi-e-commerce", "q": "How is the items array built in e-commerce events?", "a": "It is a list of objects. Each object is an item of the action ( view_item , add_to_cart , begin_checkout , purchase ). Useful fields: item_id , item_name , item_brand , item_category , price , quantity , index .", "href": "/en/faq#come-e-fatto-l-array-items-negli-eventi-e-commerce"}, {"id": "qual-e-la-differenza-tra-view-item-list-e-select-item", "q": "What is the difference between view_item_list and select_item?", "a": "view_item_list measures the view of a grid or category, with item_list_id and item_list_name . select_item measures the click on an item in that list, before the product page.", "href": "/en/faq#qual-e-la-differenza-tra-view-item-list-e-select-item"}, {"id": "come-si-traccia-il-funnel-di-acquisto-con-gli-eventi-consigliati", "q": "How do you track the purchase funnel with recommended events?", "a": "In sequence, published by the dataLayer and not by theme CSS selectors: view_item add_to_cart view_cart begin_checkout add_shipping_info and add_payment_info purchase The package that covers them is the E-commerce Tracker . The data layer is in the DataLayer guide.", "href": "/en/faq#come-si-traccia-il-funnel-di-acquisto-con-gli-eventi-consigliati"}, {"id": "cosa-succede-se-value-o-price-arrivano-come-stringa-per-esempio-99-00", "q": "What happens if value or price arrive as a string, for example \"99.00\"?", "a": "Reports and monetary metrics may add the value incorrectly or drop it. value , price and quantity must be sent as numbers.", "href": "/en/faq#cosa-succede-se-value-o-price-arrivano-come-stringa-per-esempio-99-00"}, {"id": "come-si-gestiscono-i-rimborsi-in-google-analytics", "q": "How are refunds handled in Google Analytics?", "a": "With the refund event and the same transaction_id as the original order, plus currency and the refunded value , or items if the refund is partial.", "href": "/en/faq#come-si-gestiscono-i-rimborsi-in-google-analytics"}, {"id": "come-si-inviano-gli-eventi-di-lead-generation-in-modo-standard", "q": "How do you send lead-generation events in a standard way?", "a": "With recommended events: generate_lead (also with currency and an estimated value ) and, in qualification flows, qualify_lead or close_lead . The click on phone, mailto and WhatsApp stays its own event: see Contacts 3-in-1 .", "href": "/en/faq#come-si-inviano-gli-eventi-di-lead-generation-in-modo-standard"}, {"id": "come-si-tracciano-le-single-page-application-dove-non-c-e-un-nuovo-caric", "q": "How do you track single-page applications, where there is no new HTTP load?", "a": "You turn off the automatic page_view if the first hit would be a duplicate, and you send a page_view on every view change with updated page_location and page_title . In GTM the same result comes from a dataLayer.push with a dedicated event . Installation detail: DataLayer .", "href": "/en/faq#come-si-tracciano-le-single-page-application-dove-non-c-e-un-nuovo-caric"}, {"id": "qual-e-la-differenza-tra-il-tag-nativo-ga4-in-gtm-e-gtag-event", "q": "What is the difference between the native GA4 tag in GTM and gtag('event', ...)?", "a": "In the native tag you map parameters and variables in the interface, usually after a dataLayer.push . With gtag('event', ...) the call lives in the page script. Together, on the same event, they duplicate hits.", "href": "/en/faq#qual-e-la-differenza-tra-il-tag-nativo-ga4-in-gtm-e-gtag-event"}, {"id": "come-si-evita-di-mandare-dati-personali-in-chiaro-nei-parametri-ga4", "q": "How do you avoid sending personal data in the clear in GA4 parameters?", "a": "You sanitize upstream, before the push. No email, phone or other identifying data in URLs, event names or parameters. Consent on these flows is in the Consent Mode guide.", "href": "/en/faq#come-si-evita-di-mandare-dati-personali-in-chiaro-nei-parametri-ga4"}, {"id": "cosa-significa-registrare-un-parametro-come-dimensione-o-metrica-persona", "q": "What does it mean to register a parameter as a custom dimension or metric?", "a": "GA4 receives the parameter immediately, but you see it in reports and explorations only after you create the custom dimension or metric in the property.", "href": "/en/faq#cosa-significa-registrare-un-parametro-come-dimensione-o-metrica-persona"}, {"id": "come-si-tracciano-moduli-e-download-di-file", "q": "How do you track forms and file downloads?", "a": "file_download with enhanced measurement, or a dedicated event with file_name , file_extension , link_url . form_start and form_submit , or a custom event only on a confirmed submit, not on a simple button click.", "href": "/en/faq#come-si-tracciano-moduli-e-download-di-file"}, {"id": "quali-regole-di-nome-rispettare-per-eventi-e-parametri", "q": "Which naming rules should events and parameters follow?", "a": "Lowercase snake_case , no spaces. No reserved prefixes: ga_ , google_ , firebase_ . The same name on web and app, otherwise cross-platform reports do not merge.", "href": "/en/faq#quali-regole-di-nome-rispettare-per-eventi-e-parametri"}, {"id": "come-si-verifica-che-un-evento-arrivi-con-i-parametri-giusti", "q": "How do you check that an event arrives with the right parameters?", "a": "With DebugView in Google Analytics, together with Tag Manager Preview or Tag Assistant. You check the single event and every attached parameter, not only the report total.", "href": "/en/faq#come-si-verifica-che-un-evento-arrivi-con-i-parametri-giusti"}, {"id": "che-legame-c-e-tra-gli-eventi-ga4-e-il-remarketing-in-google-ads", "q": "What is the link between GA4 events and remarketing in Google Ads?", "a": "If the properties are linked and advertising signals are allowed, GA4 events and audiences are imported into Google Ads for bidding and remarketing. Product remarketing, with feed ids, is Dynamic Remarketing , also explained in the Google Ads native tag .", "href": "/en/faq#che-legame-c-e-tra-gli-eventi-ga4-e-il-remarketing-in-google-ads"}, {"id": "cosa-succede-se-un-evento-parte-prima-che-il-tag-sia-pronto-o-prima-dell", "q": "What happens if an event fires before the tag is ready or before the consent update?", "a": "Without a queue or without Consent Mode the hit can be dropped, or it can fire with a restrictive consent state. With GTM or gtag and Consent Mode , the request follows the applied state.", "href": "/en/faq#cosa-succede-se-un-evento-parte-prima-che-il-tag-sia-pronto-o-prima-dell"}, {"id": "come-si-gestiscono-piu-proprieta-con-lo-stesso-datalayer", "q": "How do you handle multiple properties with the same dataLayer?", "a": "By routing each tag to its own Measurement ID G-XXXX , based on the trigger or the destination parameter. The queue stays one; the destinations do not.", "href": "/en/faq#come-si-gestiscono-piu-proprieta-con-lo-stesso-datalayer"}, {"id": "perche-allineare-i-nomi-evento-tra-sito-e-app", "q": "Why align event names between site and app?", "a": "So that purchase or sign_up is read as the same action on web and app. Different names split funnels and audiences.", "href": "/en/faq#perche-allineare-i-nomi-evento-tra-sito-e-app"}, {"id": "come-si-evita-di-riempire-la-pagina-di-eventi-ridondanti", "q": "How do you avoid filling the page with redundant events?", "a": "Write the taxonomy first: only events that serve analysis, funnels, conversions or bidding. Attributes go in parameters, not in ten almost identical event names.", "href": "/en/faq#come-si-evita-di-riempire-la-pagina-di-eventi-ridondanti"}, {"id": "qual-e-la-differenza-tra-un-evento-di-conversione-google-ads-e-un-evento", "q": "What is the difference between a Google Ads conversion event and a remarketing event?", "a": "The conversion records a valuable action (purchase, lead, call, signup) and feeds reports and bidding, for example Target CPA or Target ROAS. Remarketing collects browsing or product signals to build audiences. The catalog case is Dynamic Remarketing .", "href": "/en/faq#qual-e-la-differenza-tra-un-evento-di-conversione-google-ads-e-un-evento"}, {"id": "come-si-invia-una-conversione-google-ads-con-gtag-js", "q": "How do you send a Google Ads conversion with gtag.js?", "a": "With gtag('event', 'conversion', { send_to: 'AW-CONVERSION_ID/CONVERSION_LABEL', value: 0, currency: 'EUR', transaction_id: '...' }) . In GTM the same send is done with the native tag, not with custom HTML.", "href": "/en/faq#come-si-invia-una-conversione-google-ads-con-gtag-js"}, {"id": "a-cosa-serve-il-parametro-send-to", "q": "What is the send_to parameter for?", "a": "It indicates the AW-... account and the conversion label the action should be attributed to. Without a precise send_to , a site with multiple accounts sends the signal to the wrong destination.", "href": "/en/faq#a-cosa-serve-il-parametro-send-to"}, {"id": "quando-usare-transaction-id-anche-nelle-conversioni-google-ads", "q": "When should you also use transaction_id on Google Ads conversions?", "a": "On purchases and on any action the user can repeat by reloading the page. The same id stops the thank-you page from counting two conversions.", "href": "/en/faq#quando-usare-transaction-id-anche-nelle-conversioni-google-ads"}, {"id": "come-funzionano-le-conversioni-avanzate-e-come-si-passano-i-dati-utente", "q": "How do enhanced conversions work and how do you pass user data?", "a": "They add user-provided data (email, phone, name, address) to the conversion tag, processed according to Google's specifications, to recover conversions the cookie alone does not see. They must not be put in the clear in GA4 parameters. Advertising consent is in Consent Mode .", "href": "/en/faq#come-funzionano-le-conversioni-avanzate-e-come-si-passano-i-dati-utente"}, {"id": "come-si-inviano-i-dati-utente-in-gtm-lato-server-per-google-ads", "q": "How do you send user data in server-side GTM for Google Ads?", "a": "With a User-provided data variable linked to the Google tag, and with the Google Ads User-provided Data Event tag in the server container, using the correct Conversion ID.", "href": "/en/faq#come-si-inviano-i-dati-utente-in-gtm-lato-server-per-google-ads"}, {"id": "cos-e-il-remarketing-dinamico-e-in-cosa-differisce-da-quello-standard", "q": "What is dynamic remarketing and how does it differ from standard remarketing?", "a": "Standard remarketing uses lists of visited pages. Dynamic remarketing sends catalog parameters ( value , currency , items with id and google_business_vertical ) to show the items viewed or abandoned. That is the scope of Dynamic Remarketing .", "href": "/en/faq#cos-e-il-remarketing-dinamico-e-in-cosa-differisce-da-quello-standard"}, {"id": "quali-parametri-chiede-il-remarketing-dinamico-retail", "q": "Which parameters does retail dynamic remarketing require?", "a": "send_to toward the correct Ads destination. value and currency . items , and in each element an id identical to the Merchant Center feed product id. google_business_vertical , for retail usually retail .", "href": "/en/faq#quali-parametri-chiede-il-remarketing-dinamico-retail"}, {"id": "cosa-succede-se-l-id-prodotto-non-coincide-con-il-feed-merchant-center", "q": "What happens if the product id does not match the Merchant Center feed?", "a": "Google Ads does not match the user to the catalog item. The dynamic ad is not personalized, or it uses a generic fallback.", "href": "/en/faq#cosa-succede-se-l-id-prodotto-non-coincide-con-il-feed-merchant-center"}, {"id": "perche-i-modelli-di-tag-nativi-google-ads-in-gtm-e-non-un-tag-html-perso", "q": "Why native Google Ads tag templates in GTM and not a custom HTML tag?", "a": "Native templates format the parameters, talk to the Conversion Linker, respect Consent Mode and stay aligned with the latest Ads features. Custom HTML reinvents those things, and usually breaks them.", "href": "/en/faq#perche-i-modelli-di-tag-nativi-google-ads-in-gtm-e-non-un-tag-html-perso"}, {"id": "come-si-evita-la-doppia-conversione-se-il-sito-ha-sia-gtag-js-sia-gtm", "q": "How do you avoid a double conversion if the site has both gtag.js and GTM?", "a": "Keep a single system, preferably GTM with native tags, and remove the other send of the same event on the same trigger. Two tags on the same thank-you page count two conversions.", "href": "/en/faq#come-si-evita-la-doppia-conversione-se-il-sito-ha-sia-gtag-js-sia-gtm"}, {"id": "come-si-tracciano-azioni-che-non-ricaricano-la-pagina-come-un-form-ajax-", "q": "How do you track actions that do not reload the page, such as an AJAX form or a phone click?", "a": "The trigger must listen for a dataLayer event emitted only after confirmation: for example form_submitted or phone_click . The ready-made container for the number is Phone Click Tracking ; for phone, email and WhatsApp together, Contacts 3-in-1 .", "href": "/en/faq#come-si-tracciano-azioni-che-non-ricaricano-la-pagina-come-un-form-ajax-"}, {"id": "a-cosa-servono-value-e-currency-in-google-ads", "q": "What are value and currency for in Google Ads?", "a": "They measure the economic return of the conversion and feed value-based strategies: Maximize conversion value and Target ROAS. Without a currency, the value is not comparable.", "href": "/en/faq#a-cosa-servono-value-e-currency-in-google-ads"}, {"id": "come-si-distinguono-valori-variabili-e-valori-fissi", "q": "How do you distinguish variable values and fixed values?", "a": "For ecommerce and quotes the calculated value sits in the dataLayer, transaction by transaction: that is the E-commerce Tracker case. For a lead with a constant value you set a fixed amount on the Ads conversion, and you repeat it identically.", "href": "/en/faq#come-si-distinguono-valori-variabili-e-valori-fissi"}, {"id": "che-differenza-c-e-tra-importare-una-conversione-da-ga4-e-usare-il-tag-n", "q": "What is the difference between importing a conversion from GA4 and using the Google Ads native tag?", "a": "The native tag sends the signal directly to Google Ads, with Conversion Linker and enhanced conversions. The GA4 import depends on the key event and on the link between the two products, and it is less suitable when you need the first-party ad click. The native tag model is the subject of this guide.", "href": "/en/faq#che-differenza-c-e-tra-importare-una-conversione-da-ga4-e-usare-il-tag-n"}, {"id": "come-si-verifica-che-una-conversione-google-ads-parta-senza-errori", "q": "How do you check that a Google Ads conversion fires without errors?", "a": "In GTM Preview or in Tag Assistant you check triggers, variables and the consent state. In Network you look for requests to Google advertising domains, not only the green tag name.", "href": "/en/faq#come-si-verifica-che-una-conversione-google-ads-parta-senza-errori"}, {"id": "cosa-succede-se-il-tag-di-conversione-scatta-prima-che-le-variabili-sian", "q": "What happens if the conversion tag fires before the variables are ready?", "a": "value or transaction_id leave empty. Value, currency and id must be in the same dataLayer.push object that emits the event , or already in the state before that push. The queue is explained in the DataLayer guide.", "href": "/en/faq#cosa-succede-se-il-tag-di-conversione-scatta-prima-che-le-variabili-sian"}, {"id": "come-si-gestisce-il-consenso-sui-tag-di-conversione-e-remarketing", "q": "How is consent handled on conversion and remarketing tags?", "a": "With Consent Mode: ad_storage , ad_user_data for user data used in advertising, ad_personalization for remarketing and personalized ads. The detail of the default and update commands is in the Consent Mode guide. The package is Consent Mode v2 .", "href": "/en/faq#come-si-gestisce-il-consenso-sui-tag-di-conversione-e-remarketing"}, {"id": "si-puo-mandare-un-evento-a-un-solo-account-google-ads", "q": "Can you send an event to a single Google Ads account?", "a": "Yes. send_to on the tag or on the event limits the destination to that account and that label. Other accounts linked on the page do not receive that conversion.", "href": "/en/faq#si-puo-mandare-un-evento-a-un-solo-account-google-ads"}, {"id": "che-rapporto-c-e-tra-il-tag-google-su-tutte-le-pagine-e-la-precisione-de", "q": "What is the relationship between the Google tag on all pages and conversion accuracy?", "a": "A tag present across the whole site keeps first-party cookies and identifiers along the session. Without it, the Conversion Linker does not see the click on the landing page and attribution gets shorter.", "href": "/en/faq#che-rapporto-c-e-tra-il-tag-google-su-tutte-le-pagine-e-la-precisione-de"}, {"id": "cos-e-il-conversion-linker-e-a-cosa-serve", "q": "What is the Conversion Linker and what is it for?", "a": "It stores ad-click data, such as the gclid , in a first-party cookie, so the conversion tag can find it when the action happens, even pages later.", "href": "/en/faq#cos-e-il-conversion-linker-e-a-cosa-serve"}, {"id": "perche-il-conversion-linker-e-indispensabile-con-i-limiti-ai-cookie-di-t", "q": "Why is the Conversion Linker essential with third-party cookie limits?", "a": "Browsers block or shorten third-party cookies. Saving the click on the site's domain makes the conversion readable without that third-party cookie.", "href": "/en/faq#perche-il-conversion-linker-e-indispensabile-con-i-limiti-ai-cookie-di-t"}, {"id": "su-quali-pagine-deve-attivarsi-il-conversion-linker-in-gtm", "q": "On which pages should the Conversion Linker fire in GTM?", "a": "On all of them, with an All Pages trigger. Any landing page that receives an ad click must be able to save the parameter immediately.", "href": "/en/faq#su-quali-pagine-deve-attivarsi-il-conversion-linker-in-gtm"}, {"id": "come-funziona-il-conversion-linker-nel-tagging-lato-server", "q": "How does the Conversion Linker work in server-side tagging?", "a": "In the server container the Conversion Linker tag, usually on All Pages, writes and reads the first-party cookies tied to the tagging server's domain.", "href": "/en/faq#come-funziona-il-conversion-linker-nel-tagging-lato-server"}, {"id": "qual-e-la-differenza-tra-cookie-di-prima-parte-e-di-terze-parti", "q": "What is the difference between first-party and third-party cookies?", "a": "A first-party cookie is set by the domain of the page you are visiting. A third-party cookie is set by a domain different from the page's domain.", "href": "/en/faq#qual-e-la-differenza-tra-cookie-di-prima-parte-e-di-terze-parti"}, {"id": "perche-i-cookie-di-prima-parte-reggono-meglio-la-misura-di-oggi", "q": "Why do first-party cookies hold up better for measurement today?", "a": "They belong to the site being visited and escape the general block on third-party cookies. They remain subject to consent and to expiry limits imposed by the browser.", "href": "/en/faq#perche-i-cookie-di-prima-parte-reggono-meglio-la-misura-di-oggi"}, {"id": "come-browser-e-server-possono-comunque-limitare-i-cookie-di-prima-parte", "q": "How can browsers and servers still limit first-party cookies?", "a": "With ITP and duration caps, with wrong attributes ( Domain , Path , SameSite , Secure ) and with consent denied on analytics_storage or ad_storage . See Consent Mode .", "href": "/en/faq#come-browser-e-server-possono-comunque-limitare-i-cookie-di-prima-parte"}, {"id": "che-legame-c-e-tra-cookie-di-prima-parte-analytics-storage-e-il-client-i", "q": "What is the link between first-party cookies, analytics_storage and the GA4 client id?", "a": "If analytics_storage is granted, GA4 reads and writes first-party cookies to recognize the user and the session. If it is denied, it does not use that storage to identify them. Events guide: Google Analytics 4 .", "href": "/en/faq#che-legame-c-e-tra-cookie-di-prima-parte-analytics-storage-e-il-client-i"}, {"id": "che-legame-c-e-tra-cookie-di-prima-parte-ad-storage-e-conversion-linker", "q": "What is the link between first-party cookies, ad_storage and the Conversion Linker?", "a": "The linker and advertising tags store the click in first-party storage. If ad_storage is denied, that write is limited and the conversion cannot rely on the advertising cookie.", "href": "/en/faq#che-legame-c-e-tra-cookie-di-prima-parte-ad-storage-e-conversion-linker"}, {"id": "in-che-senso-il-tag-google-misura-anche-quando-i-cookie-sono-limitati", "q": "In what sense does the Google tag still measure when cookies are limited?", "a": "It combines first-party signals, linker parameters in the URL, Consent Mode and modeling. It is not a way to ignore a refusal: it is continuity of measurement inside the consent state.", "href": "/en/faq#in-che-senso-il-tag-google-misura-anche-quando-i-cookie-sono-limitati"}, {"id": "cos-e-la-misurazione-interdominio-e-quando-serve", "q": "What is cross-domain measurement and when is it needed?", "a": "It is needed when the journey crosses two distinct domains, for example the site and an external checkout, and you want the same session instead of a new user or a self-referral.", "href": "/en/faq#cos-e-la-misurazione-interdominio-e-quando-serve"}, {"id": "che-differenza-c-e-tra-sottodomini-e-domini-diversi", "q": "What is the difference between subdomains and different domains?", "a": "www.example.com and shop.example.com share the parent domain and, if the cookie is set on .example.com , the first-party cookies too. domain-a.com and domain-b.com do not: link decoration is required.", "href": "/en/faq#che-differenza-c-e-tra-sottodomini-e-domini-diversi"}, {"id": "come-il-tag-google-mantiene-l-identita-da-dominio-a-com-a-dominio-b-com", "q": "How does the Google tag keep identity from domain-a.com to domain-b.com?", "a": "It decorates outbound links and forms with a _gl parameter. The destination domain reads it and saves the state in its own first-party cookies.", "href": "/en/faq#come-il-tag-google-mantiene-l-identita-da-dominio-a-com-a-dominio-b-com"}, {"id": "quali-errori-fanno-fallire-il-cross-domain", "q": "Which mistakes make cross-domain fail?", "a": "A domain is missing from the configuration list. A server-side redirect drops the query, and therefore _gl as well. A script intercepts the click and navigates without letting the link be decorated.", "href": "/en/faq#quali-errori-fanno-fallire-il-cross-domain"}, {"id": "come-si-verifica-il-passaggio-tra-pagine-amp-e-pagine-non-amp", "q": "How do you verify the handoff between AMP pages and non-AMP pages?", "a": "In a private window, or after clearing cookies, you check that cid and any gclid travel in the _gl parameter and match on the final page. Redirects in between are the first point that breaks.", "href": "/en/faq#come-si-verifica-il-passaggio-tra-pagine-amp-e-pagine-non-amp"}, {"id": "come-influiscono-i-redirect-301-e-302-sul-conversion-linker-e-sul-cross-", "q": "How do 301 and 302 redirects affect the Conversion Linker and cross-domain?", "a": "If the redirect does not keep the query string, gclid and _gl are lost. The chain must be tested on the real arrival URL, not only on the original link.", "href": "/en/faq#come-influiscono-i-redirect-301-e-302-sul-conversion-linker-e-sul-cross-"}, {"id": "come-si-controllano-i-cookie-durante-il-debug", "q": "How do you inspect cookies during debugging?", "a": "In developer tools: the Application tab, the Cookies list, and the Network tab to see domain, expiry and request payloads.", "href": "/en/faq#come-si-controllano-i-cookie-durante-il-debug"}, {"id": "qual-e-la-checklist-di-un-tagging-robusto-su-datalayer-ga4-e-google-ads", "q": "What is the checklist for robust tagging on dataLayer, GA4 and Google Ads?", "a": "Initialize window.dataLayer only once, at the top, without reassigning it. Guide: DataLayer . Events with typed parameters, numbers that are really numbers. Guide: GA4 . Native tags, not custom HTML, for Ads and Analytics. Consent Mode with default before the tags and update from the CMP. Guide: Consent Mode .", "href": "/en/faq#qual-e-la-checklist-di-un-tagging-robusto-su-datalayer-ga4-e-google-ads"}, {"id": "cos-e-il-consent-mode-nella-tag-platform-di-google", "q": "What is Consent Mode in the Google Tag Platform?", "a": "It is the way Google tags receive the consent state and adapt cookies, identifiers and pings. It does not replace the banner: it reads the choice the banner collected. The implementation package is Consent Mode v2 .", "href": "/en/faq#cos-e-il-consent-mode-nella-tag-platform-di-google"}, {"id": "quali-parametri-di-consenso-gestisce-il-consent-mode", "q": "Which consent parameters does Consent Mode handle?", "a": "ad_storage : advertising storage. analytics_storage : analytics storage. ad_user_data : user data for advertising purposes. ad_personalization : ad personalization and remarketing. Where needed: functionality_storage , personalization_storage , security_storage .", "href": "/en/faq#quali-parametri-di-consenso-gestisce-il-consent-mode"}, {"id": "qual-e-la-differenza-tra-default-e-update", "q": "What is the difference between default and update?", "a": "default is the initial state, before tags fire. In regions that require prior consent it is often denied . update arrives when the person accepts or refuses in the CMP and replaces that state.", "href": "/en/faq#qual-e-la-differenza-tra-default-e-update"}, {"id": "perche-il-default-va-impostato-prima-che-partano-i-tag", "q": "Why must default be set before tags fire?", "a": "Because a tag that fires before default can write cookies that conflict with the initial choice. Tags on the same event must read a single, consistent state. The order relative to the queue is that of the DataLayer .", "href": "/en/faq#perche-il-default-va-impostato-prima-che-partano-i-tag"}, {"id": "perche-il-consent-mode-non-si-configura-con-un-tag-html-personalizzato", "q": "Why is Consent Mode not configured with a custom HTML tag?", "a": "Custom HTML fires at a moment that is not aligned with the queue and with tag evaluation. Use GTM's consent APIs or gtag('consent', ...) and the CMP integration.", "href": "/en/faq#perche-il-consent-mode-non-si-configura-con-un-tag-html-personalizzato"}, {"id": "come-fa-gtm-a-far-vedere-lo-stesso-aggiornamento-a-tutti-i-tag", "q": "How does GTM show the same update to every tag?", "a": "With the consent APIs and with the controls already present in native tag templates. The update is processed in the correct order relative to queued messages, not whenever it happens.", "href": "/en/faq#come-fa-gtm-a-far-vedere-lo-stesso-aggiornamento-a-tutti-i-tag"}, {"id": "cosa-succede-se-analytics-storage-e-denied", "q": "What happens if analytics_storage is denied?", "a": "Google Analytics 4 tags cannot read or write the analytics cookies used to recognize the user and the session. Cookieless pings may remain, depending on the Consent Mode configuration.", "href": "/en/faq#cosa-succede-se-analytics-storage-e-denied"}, {"id": "cosa-succede-se-ad-storage-ad-user-data-o-ad-personalization-sono-denied", "q": "What happens if ad_storage, ad_user_data or ad_personalization are denied?", "a": "Advertising storage, the sending of user data for ads purposes, or personalization, including remarketing, is limited. Google Ads tags stay compliant with the choice. Modeling, where provided, is not the same as ignoring the refusal.", "href": "/en/faq#cosa-succede-se-ad-storage-ad-user-data-o-ad-personalization-sono-denied"}, {"id": "cos-e-una-cmp-e-come-si-collega-alla-tag-platform", "q": "What is a CMP and how does it connect to the Tag Platform?", "a": "It is the system that collects and stores the choice. It integrates with GTM or gtag.js by emitting default and update , and optionally TCF v2.2. Without this bridge, the banner and the tags do not talk to each other: that is the problem Consent Mode v2 closes.", "href": "/en/faq#cos-e-una-cmp-e-come-si-collega-alla-tag-platform"}, {"id": "quali-problemi-capitano-con-le-implementazioni-iab-tcf", "q": "What problems come up with IAB TCF implementations?", "a": "Strings or purposes that are not aligned, a CMP that arrives after the tags, TCF support turned on only halfway in Google tags. Tag Assistant shows the state that was actually read, not the one the plugin promised.", "href": "/en/faq#quali-problemi-capitano-con-le-implementazioni-iab-tcf"}, {"id": "come-si-verifica-il-consent-mode-in-tag-assistant", "q": "How do you verify Consent Mode in Tag Assistant?", "a": "In the timeline, for each event, you read Default and Update for every parameter. A tag must not fire with a state different from the rules set for that moment.", "href": "/en/faq#come-si-verifica-il-consent-mode-in-tag-assistant"}, {"id": "che-ruolo-ha-il-consent-mode-nel-tagging-lato-server", "q": "What role does Consent Mode play in server-side tagging?", "a": "The state also travels to the server container. Tags that fire from the server must respect the same choice, not a second policy.", "href": "/en/faq#che-ruolo-ha-il-consent-mode-nel-tagging-lato-server"}], "products": [{"id": "phone", "name": "Phone Click Tracking", "price": "€150", "href": "/en/shop/tracking-click-telefono", "keys": ["phone", "call", "tel", "number", "click"], "why": "It measures clicks on tel: links and sends them to Google Ads and GA4. The container is ready to import."}, {"id": "email", "name": "Email Tag", "price": "€150", "href": "/en/shop/tag-email", "keys": ["email", "mailto", "mail"], "why": "It tracks clicks on mailto: links, when the lead writes instead of submitting a form."}, {"id": "facebook", "name": "Facebook Tag", "price": "€150", "href": "/en/shop/tag-facebook", "keys": ["facebook", "meta", "fbq", "pixel"], "why": "It tracks outbound clicks to Facebook or Meta."}, {"id": "instagram", "name": "Instagram Tag", "price": "€150", "href": "/en/shop/tag-instagram", "keys": ["instagram"], "why": "It counts clicks through to Instagram."}, {"id": "linkedin", "name": "LinkedIn Tag", "price": "€150", "href": "/en/shop/tag-linkedin", "keys": ["linkedin", "b2b"], "why": "It measures clicks to LinkedIn, the usual B2B lead path."}, {"id": "tre", "name": "Contacts 3-in-1", "price": "€350", "href": "/en/shop/contatti-3in1", "keys": ["whatsapp", "3 in 1", "3-in-1", "phone email"], "why": "One container for phone, email and WhatsApp. Better than buying the tags one by one."}, {"id": "social", "name": "Social Tracking 6-in-1", "price": "€450", "href": "/en/shop/tracking-social-6in1", "keys": ["6 in 1", "6-in-1", "all social", "tiktok", "youtube", "pinterest"], "why": "Several networks in one container, cheaper than buying the social tags separately."}, {"id": "ecom", "name": "Ecommerce Tracker", "price": "Quote", "href": "/en/shop/tracker-ecommerce", "keys": ["ecommerce", "e-commerce", "shopify", "woocommerce", "prestashop", "magento", "cart", "purchase", "checkout", "orders"], "why": "The purchase funnel depends on the CMS and the data layer, so it is quoted, not a fixed JSON."}, {"id": "remark", "name": "Dynamic Remarketing", "price": "Quote", "href": "/en/shop/dynamic-remarketing", "keys": ["remarketing", "retargeting", "merchant", "feed", "dynamic"], "why": "Use it when ads must show the product that was viewed. It has to match the feed, so it is quoted."}, {"id": "consent", "name": "Consent Mode v2", "price": "Quote", "href": "/en/shop/consent-mode-v2", "keys": ["consent", "cookie", "cmp", "gdpr", "banner", "iubenda", "cookiebot", "onetrust"], "why": "It connects the cookie banner to Google tags with default and update. If tags fire before the choice, measurement breaks."}, {"id": "h5", "name": "5-hour Support", "price": "€500", "href": "/en/shop/supporto-5-ore", "keys": ["5 hour", "5 hours", "audit", "quick review"], "why": "A short pack for a check: consent, one container, or an event that does not fire."}, {"id": "h10", "name": "10-hour Support", "price": "€900", "href": "/en/shop/supporto-10-ore", "keys": ["10 hour", "10 hours", "agency", "several clients"], "why": "For a wider job, or an agency with more than one container."}, {"id": "h20", "name": "20-hour Support", "price": "€1,600", "href": "/en/shop/supporto-20-ore", "keys": ["20 hour", "20 hours", "ongoing", "monthly", "retainer"], "why": "For a longer engagement that does not fit a single product page."}], "guides": [{"q": "DataLayer architecture", "a": "The dataLayer is the queue that carries events and variables to Google Tag Manager. Initialize it once, before the snippet, and do not reassign it.", "href": "/en/datalayer-architettura", "keys": ["datalayer", "data layer", "gtm", "tag manager", "push", "fifo"]}, {"q": "Google Analytics 4", "a": "GA4 separates automatic events, enhanced measurement, recommended events and custom events. A shop needs the funnel and purchase parameters, not enhanced measurement alone.", "href": "/en/tag-google-analytics-4", "keys": ["ga4", "analytics", "events", "debugview"]}, {"q": "Google Ads native tag", "a": "The Ads tag records the conversion and remarketing. The Conversion Linker and the first-party cookie keep the click attached.", "href": "/en/tag-nativo-google-ads", "keys": ["google ads", "conversion linker", "gclid", "ads conversion"]}, {"q": "Consent Mode", "a": "Consent Mode does not replace the banner. default is set before the tags, update comes from the CMP. The four parameters are ad_storage, analytics_storage, ad_user_data and ad_personalization.", "href": "/en/consent-mode", "keys": ["consent mode", "consent", "cmp", "gcs"]}, {"q": "About", "a": "Easy Tag is the spin-off of the Italian team that worked on tags at Google Krakow. The work is GTM, GA4, Ads, the data layer and consent.", "href": "/en/chi-siamo", "keys": ["who are", "about", "team", "krakow", "cracow"]}]};
  var STOP = {the:1,and:1,for:1,with:1,you:1,your:1,our:1,this:1,that:1,are:1,was:1,how:1,what:1,when:1,why:1,can:1,want:1,need:1,from:1,into:1,about:1,have:1,has:1,not:1,but:1,its:1};

  function norm(s) {
    return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
  }
  function tokens(s) {
    var out = [];
    norm(s).split(" ").forEach(function (w) {
      if (w.length >= 3 && !STOP[w]) out.push(w);
    });
    return out;
  }
  function has(text, key) {
    return norm(text).indexOf(norm(key)) !== -1;
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      if (c === "&") return "&" + "amp;";
      if (c === "<") return "&" + "lt;";
      if (c === ">") return "&" + "gt;";
      return "&" + "quot;";
    });
  }
  function scoreText(query, text) {
    var qt = tokens(query);
    var blob = norm(text);
    var s = 0;
    qt.forEach(function (w) {
      if (blob.indexOf(w) !== -1) s += 1;
    });
    return s;
  }

  function matchProducts(query) {
    var hits = [];
    KB.products.forEach(function (p) {
      var s = 0;
      p.keys.forEach(function (k) {
        if (has(query, k)) s += k.indexOf(" ") !== -1 ? 4 : 2;
      });
      if (s) hits.push({ p: p, s: s });
    });
    hits.sort(function (a, b) { return b.s - a.s; });
    var socialIds = { facebook: 1, instagram: 1, linkedin: 1 };
    var socials = hits.filter(function (h) { return socialIds[h.p.id]; });
    if (socials.length >= 2) {
      hits = hits.filter(function (h) { return !socialIds[h.p.id]; });
      var pack = KB.products.filter(function (p) { return p.id === "social"; })[0];
      hits.unshift({ p: pack, s: 8 });
    }
    var contactish = hits.filter(function (h) { return h.p.id === "phone" || h.p.id === "email"; });
    if (has(query, "whatsapp") && contactish.length) {
      hits = hits.filter(function (h) { return h.p.id !== "phone" && h.p.id !== "email"; });
      var tre = KB.products.filter(function (p) { return p.id === "tre"; })[0];
      hits.unshift({ p: tre, s: 8 });
    }
    var seen = {};
    return hits.filter(function (h) {
      if (seen[h.p.id]) return false;
      seen[h.p.id] = 1;
      return true;
    }).slice(0, 2);
  }

  function bestFaq(query) {
    var best = null;
    KB.faqs.forEach(function (f) {
      var qHits = scoreText(query, f.q);
      var s = qHits * 3 + scoreText(query, f.a);
      if (!best || s > best.s) best = { f: f, s: s, qHits: qHits };
    });
    return best && best.qHits >= 2 ? best : null;
  }
  function bestGuide(query) {
    var best = null;
    KB.guides.forEach(function (g) {
      var s = 0;
      g.keys.forEach(function (k) { if (has(query, k)) s += 3; });
      s += scoreText(query, g.q + " " + g.a);
      if (!best || s > best.s) best = { g: g, s: s };
    });
    return best && best.s >= 3 ? best : null;
  }

  function reply(raw) {
    var query = String(raw || "").trim();
    var n = norm(query);
    if (!n || /^(hi|hello|hey|good morning|good afternoon)$/.test(n)) {
      return {
        text: "Hi. I answer from the guides and FAQs on this site. Tell me what you need to measure: a click, an online shop, Google Ads, consent, or hands-on work in the container.",
        cards: [],
        links: [{ label: "View the shop", href: "/en/shop" }, { label: "Technical collaboration", href: "/en/contatti" }]
      };
    }
    if (/\b(price|prices|cost|how much)\b/.test(n) && tokens(query).length <= 4) {
      return {
        text: "Ready-made containers start at €150, VAT included. Phone, email and each social tag are €150. Contacts 3-in-1 is €350. Social 6-in-1 is €450. Hour packs run from €500 to €1,600. Ecommerce, dynamic remarketing and Consent Mode are quoted, because they depend on the site.",
        cards: [],
        links: [{ label: "Open the shop", href: "/en/shop" }]
      };
    }
    var collab = /collaborat|agency|consult|custom|audit|support|\bhours\b|retainer|engagement/.test(n);
    var products = matchProducts(query);
    var faq = bestFaq(query);
    if (faq && products.length && faq.qHits < 3) faq = null;
    var guide = bestGuide(query);
    var parts = [];
    var cards = [];
    var links = [];

    products.forEach(function (h) { cards.push(h.p); });
    if (faq) {
      parts.push(faq.f.a);
      links.push({ label: "Open the FAQ", href: faq.f.href });
    } else if (guide && !products.length) {
      parts.push(guide.g.a);
      links.push({ label: "Open the guide", href: guide.g.href });
    }
    if (collab) {
      parts.push("If a ready-made container is not enough, use the Contact page for an audit or a technical collaboration. A narrow check fits the 5-hour pack.");
      if (!cards.some(function (c) { return c.id === "h5"; })) {
        cards.push(KB.products.filter(function (p) { return p.id === "h5"; })[0]);
      }
      links.push({ label: "Contact us", href: "/en/contatti" });
    }
    cards = cards.slice(0, 2);
    if (cards.length) {
      parts.unshift(cards.length > 1
        ? "These are the closest product pages, based on what you wrote. The reason is under each one."
        : "This is the closest product page. The note under it says why it fits, not a generic suggestion.");
    }
    if (!parts.length) {
      parts.push("There is no precise FAQ on that. Browse the questions, or tell me the CMS, what you want to count, and whether a cookie banner is already installed.");
      links.push({ label: "All FAQs", href: "/en/faq" });
      links.push({ label: "Contact", href: "/en/contatti" });
    } else if (!links.some(function (l) { return l.href === "/shop"; }) && cards.length) {
      links.push({ label: "Shop", href: "/en/shop" });
    }
    return { text: parts.join(" "), cards: cards, links: links.slice(0, 3) };
  }

  if (typeof document === "undefined") {
    globalThis.ETChat = { reply: reply };
    return;
  }

  var css = ""
    + ".et-chat-btn{position:fixed;right:18px;bottom:18px;z-index:9999;width:58px;height:58px;border:0;border-radius:50%;background:#1182DE;color:#fff;box-shadow:0 8px 24px rgba(17,130,222,.35);cursor:pointer;display:grid;place-items:center}"
    + ".et-chat-btn:focus-visible,.et-chat-send:focus-visible,.et-chat-x:focus-visible,.et-chip:focus-visible{outline:3px solid #0B5CAD;outline-offset:2px}"
    + ".et-chat-panel{position:fixed;right:18px;bottom:86px;z-index:9999;width:min(380px,calc(100vw - 24px));height:min(560px,calc(100vh - 110px));background:#fff;border:1px solid #E8EAED;border-radius:16px;box-shadow:0 16px 50px rgba(0,0,0,.16);display:flex;flex-direction:column;overflow:hidden;font-family:Inter,Arial,sans-serif;color:#202124}"
    + ".et-chat-panel[hidden]{display:none}"
    + ".et-chat-h{background:#1182DE;color:#fff;padding:12px 14px;display:flex;justify-content:space-between;gap:8px;align-items:flex-start}"
    + ".et-chat-h strong{display:block;font-size:15px}.et-chat-h span{display:block;font-size:12px;opacity:.9;font-weight:500}"
    + ".et-chat-x{background:transparent;border:0;color:#fff;font-size:22px;line-height:1;cursor:pointer;padding:0 4px}"
    + ".et-chat-log{flex:1;overflow:auto;padding:12px;background:#F8F9FA;display:flex;flex-direction:column;gap:8px}"
    + ".et-msg{max-width:92%;padding:10px 12px;border-radius:12px;font-size:14px;line-height:1.45}"
    + ".et-msg.bot{background:#fff;border:1px solid #E8EAED;align-self:flex-start}"
    + ".et-msg.user{background:#1182DE;color:#fff;align-self:flex-end}"
    + ".et-card{display:block;margin-top:8px;padding:8px 10px;border-radius:10px;background:#E8F3FC;color:#0B5CAD;text-decoration:none}"
    + ".et-card b{display:block;color:#202124}.et-card i{display:block;font-style:normal;color:#5F6368;font-size:12.5px;margin-top:2px}.et-card em{font-style:normal;font-weight:700}"
    + ".et-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}"
    + ".et-links a{font-size:12.5px;font-weight:700;color:#1182DE;text-decoration:none;background:#fff;border:1px solid #D0E8F9;border-radius:99px;padding:4px 8px}"
    + ".et-chips{display:flex;gap:6px;flex-wrap:wrap;padding:8px 12px 0;background:#fff}"
    + ".et-chip{border:1px solid #E8EAED;background:#fff;border-radius:99px;padding:6px 10px;font-size:12.5px;cursor:pointer;color:#202124}"
    + ".et-chat-form{display:flex;gap:8px;padding:10px;border-top:1px solid #E8EAED;background:#fff}"
    + ".et-chat-form input{flex:1;border:1px solid #E8EAED;border-radius:10px;padding:10px;font:inherit;font-size:14px}"
    + ".et-chat-send{background:#1182DE;color:#fff;border:0;border-radius:10px;padding:0 12px;font-weight:700;cursor:pointer}"
    + "@media(max-width:640px){.et-chat-panel{right:12px;bottom:78px;height:min(70vh,560px)}}"
    + "@media(prefers-reduced-motion:reduce){.et-chat-btn,.et-chat-panel{transition:none}}";

  var style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  var btn = document.createElement("button");
  btn.type = "button";
  btn.className = "et-chat-btn";
  btn.setAttribute("aria-label", "Open chat");
  btn.setAttribute("aria-expanded", "false");
  btn.setAttribute("aria-controls", "et-chat-panel");
  btn.innerHTML = '<svg width="26" height="26" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="#fff" stroke-width="2"><path d="M5 6h14v9H8l-3 3V6z"/></svg>';

  var panel = document.createElement("section");
  panel.id = "et-chat-panel";
  panel.className = "et-chat-panel";
  panel.hidden = true;
  panel.setAttribute("role", "dialog");
  panel.setAttribute("aria-label", "Chat Easy Tag");
  panel.innerHTML = ''
    + '<div class="et-chat-h"><div><strong>Easy Tag</strong><span>Answers from this site, to pick the right container</span></div><button type="button" class="et-chat-x" aria-label="Close chat">×</button></div>'
    + '<div class="et-chips"></div>'
    + '<div class="et-chat-log" aria-live="polite"></div>'
    + '<form class="et-chat-form"><input type="text" name="q" autocomplete="off" placeholder="e.g. phone clicks, Shopify, cookies…" aria-label="Message"><button class="et-chat-send" type="submit">Send</button></form>';

  document.body.appendChild(panel);
  document.body.appendChild(btn);

  var log = panel.querySelector(".et-chat-log");
  var chips = panel.querySelector(".et-chips");
  var form = panel.querySelector("form");
  var input = form.querySelector("input");
  var history = [];
  try { history = JSON.parse(sessionStorage.getItem("et-chat-en") || "[]"); } catch (e) { history = []; }

  ["Phone clicks", "Online shop", "Cookies and consent", "Collaboration"].forEach(function (label) {
    var c = document.createElement("button");
    c.type = "button";
    c.className = "et-chip";
    c.textContent = label;
    c.addEventListener("click", function () { say(label); });
    chips.appendChild(c);
  });

  function bubble(role, html) {
    var el = document.createElement("div");
    el.className = "et-msg " + role;
    el.innerHTML = html;
    log.appendChild(el);
    log.scrollTop = log.scrollHeight;
  }
  function render(item) {
    if (item.role === "user") bubble("user", esc(item.text));
    else bubble("bot", item.html);
  }
  function paint(res) {
    var html = "<p>" + esc(res.text) + "</p>";
    res.cards.forEach(function (c) {
      html += '<a class="et-card" href="' + esc(c.href) + '"><b>' + esc(c.name) + '</b><i>' + esc(c.why) + '</i><em>' + esc(c.price) + ' · apri la scheda</em></a>';
    });
    if (res.links.length) {
      html += '<div class="et-links">';
      res.links.forEach(function (l) {
        html += '<a href="' + esc(l.href) + '">' + esc(l.label) + '</a>';
      });
      html += "</div>";
    }
    return html;
  }
  function say(text) {
    var clean = text.trim();
    if (!clean) return;
    history.push({ role: "user", text: clean });
    render(history[history.length - 1]);
    var res = reply(clean);
    var html = paint(res);
    history.push({ role: "bot", html: html });
    render(history[history.length - 1]);
    try { sessionStorage.setItem("et-chat", JSON.stringify(history.slice(-30))); } catch (e) {}
    input.value = "";
  }
  function setOpen(open) {
    panel.hidden = !open;
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    btn.setAttribute("aria-label", open ? "Close chat" : "Open chat");
    if (open) {
      if (!history.length) {
        var first = reply("ciao");
        history.push({ role: "bot", html: paint(first) });
        render(history[0]);
        try { sessionStorage.setItem("et-chat", JSON.stringify(history)); } catch (e) {}
      }
      setTimeout(function () { input.focus(); }, 30);
    } else btn.focus();
  }
  history.forEach(render);
  btn.addEventListener("click", function () { setOpen(panel.hidden); });
  panel.querySelector(".et-chat-x").addEventListener("click", function () { setOpen(false); });
  form.addEventListener("submit", function (e) { e.preventDefault(); say(input.value); });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !panel.hidden) setOpen(false);
  });
})();
